#!/usr/bin/env node
/**
 * Builds the Line Party sim bundle for the backend's Node replay sidecar.
 *
 *   node tools/build-sim-bundle.mjs [--out <dir>] [--app]
 *
 * --app also writes src/games-registry/simBundle.ts (SIM_BUNDLE = the hash),
 * which the app sends at join and on every submit (design 11.2 version
 * hygiene). The registry never imports that file, so the hash is stable.
 *
 * Transpiles src/games-registry/partySims.ts and its relative imports (the
 * sims are dependency-free by rule) into one CommonJS file named by the SHA-256
 * of its content: party-sims.<hash12>.cjs. The sidecar loads every bundle in
 * its bundles/ folder and routes each replay by {game, sim_version}, so older
 * app builds keep verifying after a sim change (design 11.3).
 *
 * No bundler dependency: TypeScript's transpileModule plus a tiny module map.
 * Any bare-package import is an error, which keeps the sims pure.
 */
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);
const ts = require(path.join(root, 'node_modules/typescript'));
const ENTRY = 'src/games-registry/partySims.ts';

function resolveFile(fromDir, specifier) {
  const base = path.resolve(fromDir, specifier);
  for (const c of [base, `${base}.ts`, path.join(base, 'index.ts')]) {
    if (fs.existsSync(c) && fs.statSync(c).isFile()) return c;
  }
  throw new Error(`build-sim-bundle: cannot resolve ${specifier} from ${fromDir}`);
}

export function buildBundle() {
  const modules = new Map();
  const visit = (full) => {
    const id = path.relative(root, full).split(path.sep).join('/');
    if (modules.has(id)) return id;
    modules.set(id, null);
    const src = fs.readFileSync(full, 'utf8');
    let code = ts.transpileModule(src, {
      compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2020, esModuleInterop: false, removeComments: true },
      fileName: full,
    }).outputText;
    if (/\bMath\.random\b|\bDate\b|\bperformance\b/.test(code)) throw new Error(`${id}: sims must not read Math.random or the clock`);
    code = code.replace(/require\("([^"]+)"\)/g, (_, spec) => {
      if (!spec.startsWith('.')) throw new Error(`${id}: bare import "${spec}" is not allowed in a party sim`);
      return `__req(${JSON.stringify(visit(resolveFile(path.dirname(full), spec)))})`;
    });
    modules.set(id, code);
    return id;
  };
  const entry = visit(path.join(root, ENTRY));
  const body = [...modules].map(([id, code]) => `${JSON.stringify(id)}: function (module, exports, __req) {\n${code}\n}`).join(',\n');
  const core = `'use strict';\n/* Line Party sim bundle, generated by tools/build-sim-bundle.mjs from ${ENTRY}. Do not edit. */\n` +
    `const __defs = {\n${body}\n};\nconst __cache = {};\n` +
    `function __req(id) { if (__cache[id]) return __cache[id].exports; const m = { exports: {} }; __cache[id] = m; __defs[id](m, m.exports, __req); return m.exports; }\n` +
    `const registry = __req(${JSON.stringify(entry)});\n`;
  const hash = createHash('sha256').update(core).digest('hex').slice(0, 12);
  const code = `${core}module.exports = { SIM_BUNDLE: ${JSON.stringify(hash)}, PARTY_SIMS: registry.PARTY_SIMS };\n`;
  return { hash, code, name: `party-sims.${hash}.cjs` };
}

export function appHashFile(hash) {
  return `/**\n * Generated by tools/build-sim-bundle.mjs --app. Do not edit.\n * The content hash of the party sim bundle this build plays: sent at join and\n * on every submit so the server can match it to the replay bundle (design 11.2).\n */\nexport const SIM_BUNDLE = '${hash}';\n`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const i = process.argv.indexOf('--out');
  const out = path.resolve(i > 0 ? process.argv[i + 1] : path.join(root, 'dist/sim'));
  fs.mkdirSync(out, { recursive: true });
  const { name, code, hash } = buildBundle();
  fs.writeFileSync(path.join(out, name), code);
  if (process.argv.includes('--app')) {
    fs.writeFileSync(path.join(root, 'src/games-registry/simBundle.ts'), appHashFile(hash));
  }
  const games = require(path.join(out, name)).PARTY_SIMS;
  console.log(`${path.join(out, name)} (${code.length} bytes) sim_bundle=${hash} games=${Object.values(games).map((g) => `${g.key}@${g.version}`).join(',')}`);
}
